from __future__ import annotations

import json
from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import PRODUCT_FULL_NAME, TAGLINE
from .game_forge_models import ENGINE_REGISTRY
from .plans import GAME_CREATE, GAME_CREATE_UNLIMITED

router = APIRouter(tags=["Pulsar Game Forge Portal"])


@router.get("/game-creation", response_class=HTMLResponse, include_in_schema=False)
def game_creation_portal(request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        return RedirectResponse("/signin?next=/game-creation", status_code=303)
    can_create = member.plan.has(GAME_CREATE)
    unlimited = member.plan.has(GAME_CREATE_UNLIMITED)
    flags = json.dumps({"create": can_create, "unlimited": unlimited, "plan": member.plan.name})
    engines = json.dumps(ENGINE_REGISTRY)
    page = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='robots' content='noindex,nofollow'><title>Game Creation — __BRAND__</title><style>
:root{--bg:#03050b;--panel:#0d1220;--line:#ffffff20;--gold:#efca6d;--violet:#986cff;--cyan:#5be1ff;--green:#79dda5;--red:#ff8fa5;--muted:#bac3d4}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% 0,#42156877,transparent 31%),radial-gradient(circle at 90% 5%,#123c6877,transparent 27%),#03050b;color:#fff;font-family:Inter,system-ui,sans-serif}button,input,select,textarea{font:inherit}.wrap{width:min(1480px,calc(100% - 24px));margin:auto}.nav{position:sticky;top:0;z-index:20;background:#05070dee;backdrop-filter:blur(16px);border-bottom:1px solid var(--line)}.navin{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.brand{font-weight:950}.brand small{display:block;color:var(--gold);font-size:.66rem;text-transform:uppercase;letter-spacing:.1em}.btn,button{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:10px;padding:9px 11px;font-weight:850;cursor:pointer;text-decoration:none}.primary{border:0;background:linear-gradient(120deg,var(--gold),var(--violet));color:#160c1d}.good{border-color:#79dda566;color:var(--green)}.danger{border-color:#ff8fa566;color:#ffd7df}.hero{padding:40px 0 20px}h1{font-size:clamp(2.7rem,7vw,6rem);line-height:.9;letter-spacing:-.055em;margin:.15em 0}.lead,.muted{color:var(--muted);line-height:1.6}.grid{display:grid;grid-template-columns:1.15fr .85fr;gap:12px;padding-bottom:70px}.card{border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,#111729e8,#090d18ed);padding:15px;margin-bottom:11px}.eyebrow{color:var(--gold);font-size:.68rem;text-transform:uppercase;letter-spacing:.14em;font-weight:950}.form{display:grid;gap:9px}.two{display:grid;grid-template-columns:1fr 1fr;gap:8px}input,select,textarea{width:100%;border:1px solid var(--line);background:#070a12;color:white;border-radius:10px;padding:10px}textarea{min-height:90px}.game{border:1px solid var(--line);border-radius:14px;background:#ffffff05;padding:12px;margin:9px 0}.row{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:.7rem;margin:2px}.pill.good{color:var(--green)}.pill.bad{color:#ffd4dc;border-color:#ff8fa566}.engines{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.engine{border:1px solid var(--line);border-radius:12px;padding:10px;background:#ffffff04}.engine.native{border-color:#efca6d66;background:linear-gradient(145deg,#efca6d12,#986cff12)}.rating{border-left:3px solid var(--cyan);padding-left:10px}.notice{display:none;padding:10px;border:1px solid var(--line);border-radius:10px;margin-top:10px}.notice.show{display:block}.empty{padding:20px;text-align:center;border:1px dashed #ffffff2b;border-radius:12px;color:var(--muted)}@media(max-width:930px){.grid{grid-template-columns:1fr}.engines,.two{grid-template-columns:1fr}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/dashboard'>__BRAND__<small>Aura Game Creation · __TAGLINE__</small></a><div><span class='pill'>__PLAN__</span> <a class='btn' href='/dashboard'>Dashboard</a> <a class='btn' href='/studio'>Creative Studio</a></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>Aura-native AI game creation</div><h1>Describe it. Aura creates the game system.</h1><p class='lead'>Aura owns the Game DNA, scene logic, creation workflow, editing model, safety/rating preflight and primary 2D/3D runtime. Open-source engines can be used later as optional export or compatibility targets, but they are not the core creator.</p><div id='notice' class='notice'></div></section><section class='grid'><div><div id='creatorCard' class='card'><div class='eyebrow'>New Aura Game DNA</div><h2>Create an active game workspace</h2><div id='tierRule' class='muted'></div><form id='createForm' class='form'><div class='two'><input name='title' placeholder='Game title' required maxlength='160'><input name='genre' placeholder='Genre / niche, e.g. fantasy RPG' value='adventure' required></div><div class='two'><select name='dimension'><option value='2d'>2D</option><option value='3d'>3D</option></select><select name='engine_target' id='engineSelect'><option value='aura2d'>Aura Game Engine 2D · native</option><option value='aura3d'>Aura Game Engine 3D · native</option><option value='phaser4'>Phaser 4 · optional 2D export adapter</option><option value='playcanvas'>PlayCanvas · optional 3D export adapter</option><option value='babylon'>Babylon.js · optional 3D/WebXR export adapter</option><option value='godot'>Godot · optional native/export adapter</option></select></div><textarea name='prompt' placeholder='Describe the game: world, mechanics, characters, objectives, camera, progression, art style, enemies, puzzles, etc.' required></textarea><textarea name='synopsis' placeholder='Story/synopsis (optional)'></textarea><textarea name='art_direction' placeholder='Graphics/art direction (optional)'></textarea><textarea name='audio_direction' placeholder='Music, ambience, voice and SFX direction (optional)'></textarea><label class='muted'><input name='rights_confirmed' type='checkbox' style='width:auto' required> I own or have permission to use the assets/references I ask Aura to incorporate.</label><button class='primary' type='submit'>Create Game with Aura</button></form></div><div class='card'><div class='row'><div><div class='eyebrow'>My games</div><h2>Editable Aura Game DNA</h2></div><button onclick='loadMine()'>Refresh</button></div><div id='mine'><div class='empty'>Loading…</div></div></div></div><aside><div class='card'><div class='eyebrow'>Aura Game Engine</div><h2>Native first. Export anywhere.</h2><div id='engines' class='engines'></div><p class='muted'><b>Aura Game Engine 2D and 3D are the primary targets.</b> The external entries are optional adapters Aura may export to when a platform, feature or deployment route benefits from them. The Game DNA remains Aura-owned and editable regardless of export target.</p></div><div class='card rating'><div class='eyebrow'>Ratings & worldwide preflight</div><h3>Pulsar Safety & Rating Assessment</h3><p class='muted'>Aura can estimate age suitability, descriptors and regional rating ranges, and can block unsafe/non-compliant public tests. It is <b>not</b> an official ESRB, PEGI, IARC, Australian Classification or other authority rating. Official ratings are shown only after a genuine external/storefront result is verified.</p></div><div class='card'><div class='eyebrow'>Free playtest gallery</div><h2>Approved community tests</h2><p class='muted'>Free members can play builds that passed the current content-hash safety/rating preflight. Use Pop Out to give TikTok LIVE Studio a clean window to capture.</p><div id='gallery'><div class='empty'>Loading…</div></div></div></aside></section></main><script>
const FLAGS=__FLAGS__,ENGINES=__ENGINES__;const $=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function notice(v,bad=false){let n=$('notice');n.textContent=v;n.className='notice show';n.style.borderColor=bad?'#ff8fa566':'#79dda566';clearTimeout(window._nt);window._nt=setTimeout(()=>n.className='notice',6500)}async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch{}if(!r.ok)throw new Error(typeof b.detail==='string'?b.detail:(b.detail?.message||`Request failed (${r.status})`));return b}
function bootEngines(){$('engines').innerHTML=Object.entries(ENGINES).map(([id,e])=>`<div class='engine ${e.native?'native':''}'><b>${esc(e.label)}</b><div class='muted'>${esc(e.role)}</div><span class='pill'>${esc(e.license)}</span><span class='pill'>${esc(e.dimension)}</span>${e.native?'<span class="pill good">Aura native</span>':'<span class="pill">optional adapter</span>'}</div>`).join('')}function tier(){if(!FLAGS.create){$('createForm').style.display='none';$('tierRule').textContent='Free is the play/test tier. Upgrade to Basic to create games.'}else if(FLAGS.unlimited){$('tierRule').textContent='Pro: unlimited active Aura Game DNA workspaces. External GPU/provider work still uses fair-use queues.'}else $('tierRule').textContent='Basic: one active editable game at a time. Finish/archive it before starting the next.'}
$('createForm').addEventListener('change',e=>{if(e.target.name==='dimension')$('engineSelect').value=e.target.value==='3d'?'aura3d':'aura2d'});$('createForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);const body={title:f.get('title'),genre:f.get('genre'),dimension:f.get('dimension'),engine_target:f.get('engine_target'),prompt:f.get('prompt'),synopsis:f.get('synopsis'),art_direction:f.get('art_direction'),audio_direction:f.get('audio_direction'),rights_confirmed:!!f.get('rights_confirmed'),rights_attestation:'Creator confirmed ownership/authorization in Game Creation workspace.'};try{const g=await api('/api/game-forge/games',{method:'POST',body:JSON.stringify(body)});e.target.reset();notice(`Aura Game DNA created: ${g.title}`);await loadMine()}catch(err){notice(err.message,true)}})
async function loadMine(){try{const d=await api('/api/game-forge/games');$('mine').innerHTML=d.games.length?d.games.map(gameCard).join(''):'<div class="empty">No game projects yet.</div>';if(!FLAGS.unlimited&&FLAGS.create&&d.active_editable_count>=1)$('createForm').style.opacity='.55';else $('createForm').style.opacity='1'}catch(e){$('mine').innerHTML=`<div class='empty'>${esc(e.message)}</div>`}}function gameCard(g){const r=g.rating_assessment,b=g.latest_build;return `<div class='game'><div class='row'><div><b>${esc(g.title)}</b><div><span class='pill'>${esc(g.status)}</span><span class='pill'>${esc(g.dimension)}</span><span class='pill'>${esc(g.engine_target)}</span>${r?`<span class='pill ${r.public_test_allowed?'good':'bad'}'>Pulsar ${esc(r.suggested_age_band)}</span>`:''}</div></div><div>${b?`<a class='btn' target='_blank' rel='noopener noreferrer' href='/game-creation/play/${encodeURIComponent(g.id)}'>Play</a>`:''}</div></div><p class='muted'>${esc(g.synopsis||g.genre)}</p>${r?.blockers?.length?`<div class='muted' style='color:#ffd2da'>${r.blockers.map(esc).join(' · ')}</div>`:''}<div class='row'><div><button onclick="act('${g.id}','build')">Build Playtest</button> <button onclick="act('${g.id}','scan')">Scan Rating</button> ${r?.public_test_allowed&&b?`<button class='good' onclick="act('${g.id}','publish-test')">Publish Free Test</button>`:''}</div><div>${['draft','building','review_ready'].includes(g.status)?`<button onclick="act('${g.id}','archive')">Finish / Archive</button>`:`<button onclick="act('${g.id}','reopen')">Reopen to Edit</button>`}</div></div>${g.public_id?`<p><a class='btn good' target='_blank' rel='noopener noreferrer' href='/game-gallery/${encodeURIComponent(g.public_id)}'>Open Public Test</a></p>`:''}</div>`}async function act(id,action){try{const d=await api(`/api/game-forge/games/${encodeURIComponent(id)}/${action}`,{method:'POST',body:'{}'});notice(action==='scan'?`Assessment complete: ${d.suggested_age_band}. ${d.public_test_allowed?'Eligible for public testing.':'Review blockers before publishing.'}`:`${action.replaceAll('-',' ')} complete.`);await loadMine();await loadGallery()}catch(e){notice(e.message,true)}}
async function loadGallery(){try{const d=await api('/api/game-forge/gallery');$('gallery').innerHTML=d.games.length?d.games.map(g=>`<div class='game'><b>${esc(g.title)}</b><div class='muted'>${esc(g.genre)} · Pulsar ${esc(g.suggested_age_band||'assessment')}</div><p><a class='btn good' target='_blank' rel='noopener noreferrer' href='/game-gallery/${encodeURIComponent(g.public_id)}'>Play Test</a> <a class='btn' target='_blank' rel='noopener noreferrer' href='/game-gallery/${encodeURIComponent(g.public_id)}?popout=1'>Pop Out</a></p></div>`).join(''):'<div class="empty">No approved public test builds yet.</div>'}catch(e){$('gallery').innerHTML=`<div class='empty'>${esc(e.message)}</div>`}}bootEngines();tier();loadMine();loadGallery();
</script></body></html>"""
    return HTMLResponse(
        page.replace("__BRAND__", escape(PRODUCT_FULL_NAME))
        .replace("__BRAND__", escape(PRODUCT_FULL_NAME))
        .replace("__TAGLINE__", escape(TAGLINE))
        .replace("__PLAN__", escape(member.plan.name))
        .replace("__FLAGS__", flags)
        .replace("__ENGINES__", engines),
        headers={"Cache-Control": "no-store"},
    )
